import java.util.List;
import java.util.stream.Collectors;

// A small companion program you can run to watch the two new stream steps work.
public class MarketDemo {
    public static void main(String[] args) {
        List<String> vendorNames = List.of(
                "Sunny Acres", "Baker's Lane", "Hilltop Honey", "Baker's Lane", "Sunny Acres");

        List<String> sortedVendors = vendorNames.stream()
                .distinct()
                .sorted()
                .collect(Collectors.toList());
        System.out.println("Vendors (sorted): " + sortedVendors);

        List<String> bakersLaneMenu = List.of(
                "Sourdough Loaf - $6.50",
                "Rye Boule - $7.25",
                "Baguette - $4.00",
                "Cinnamon Roll - $3.75");

        List<String> firstThree = bakersLaneMenu.stream()
                .limit(3)
                .collect(Collectors.toList());
        System.out.println("\nBaker's Lane menu (limited to 3):");
        firstThree.forEach(System.out::println);
    }
}
